const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and parameters
  const point = ee.Geometry.Point([49.357405, 39.014501]);
  const buffer = point.buffer(4000); // 4 km buffer
  const scale = 20; // SCL band resolution in meters

  // Date ranges: ±2 days around target dates
  const date1Start = '2022-11-17';
  const date1End = '2022-11-21';
  const date2Start = '2023-02-11';
  const date2End = '2023-02-17';

  // 2. Function to get least cloudy Sentinel-2 image in date range
  function getS2Image(startDate, endDate, geometry) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
      .sort('CLOUDY_PIXEL_PERCENTAGE');
    return col.first();
  }

  // 3. Function to count land and valid pixels
  function countLandPixels(image, geometry) {
    if (!image || !image.bandNames().size().getInfo()) {
      return { valid: 0, land: 0, hasImage: false };
    }
    const scl = image.select('SCL');
    // Land classes: 4 (vegetation), 5 (bare ground)
    const landMask = scl.eq(4).or(scl.eq(5));
    // Valid pixels: not cloud, shadow, cirrus, no-data, defective
    const validMask = scl.neq(0)
      .and(scl.neq(1))
      .and(scl.neq(3))
      .and(scl.neq(8))
      .and(scl.neq(9))
      .and(scl.neq(10));

    const validCount = validMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('SCL');

    const landCount = landMask.updateMask(validMask).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('SCL');

    return {
      valid: validCount.getInfo(),
      land: landCount.getInfo(),
      hasImage: true
    };
  }

  // 4. Get and process images for both dates
  let img1 = getS2Image(date1Start, date1End, buffer);
  let img2 = getS2Image(date2Start, date2End, buffer);

  // Check if images exist
  const size1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer).filterDate(date1Start, date1End).size().getInfo();
  const size2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer).filterDate(date2Start, date2End).size().getInfo();

  console.log(`2022-11-19 window: ${size1} images`);
  console.log(`2023-02-13 window: ${size2} images`);

  // Fallback to Landsat if no Sentinel-2 images (C1 early detection)
  if (size1 === 0 || size2 === 0) {
    console.log('C1: Empty Collection (no images for one/both dates)');
    console.log('<answer>C1</answer>');
    return;
  }

  const result1 = countLandPixels(img1, buffer);
  const result2 = countLandPixels(img2, buffer);

  console.log(`2022-11-19: Valid pixels=${result1.valid}, Land pixels=${result1.land}`);
  console.log(`2023-02-13: Valid pixels=${result2.valid}, Land pixels=${result2.land}`);

  // 5. Validate results
  // Case C2: No valid pixels after masking
  if (result1.valid === 0 || result2.valid === 0) {
    console.log('C2: No Valid Pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // Case C3: Invalid calculations
  if (result1.land === null || result2.land === null ||
      isNaN(result1.land) || isNaN(result2.land)) {
    console.log('C3: Calculation Failure (null/NaN)');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Determine final answer
  const islandAppeared = (result1.land === 0 && result2.land > 0);

  if (islandAppeared) {
    console.log('A: Yes (island present in 2023, absent in 2022)');
    console.log('<answer>A</answer>');
  } else {
    console.log('B: No (island did not appear as described)');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
